function spawnClone(){const a=rnd(0,Math.PI*2);clones.push({x:p.x+Math.cos(a)*(p.r+12),y:p.y+Math.sin(a)*(p.r+12),r:Math.max(9,p.r*.58),hp:p.cloneHp,max:p.cloneHp,cd:0,spikeCd:rnd(0,.45),angle:a,jx:0,jy:0,jvx:0,jvy:0,mvx:0,mvy:0})}
const rareMutations=[
["Cannibalism","Touch a dormant clone to consume it for 22 HP, resetting its 30-second revival timer.","cannibalism"],
["Emergency Mitosis","A heavy hit sheds a temporary decoy organism. 12 second cooldown.","emergency"],
["Necrotic Burst","A clone death releases a damaging biological shockwave.","necrotic"],
["Hypermetabolism","Biomass pickups briefly increase movement speed.","hyper"],
["Predatory Membrane","Close-range kills restore a little health, capped to prevent immortal melee builds.","predatory"],["Electrogenesis","Generate a constant bioelectric field around your organism. The field deals 3 damage per tick at Level I and gains +3 damage per level, up to Level IV.","electrogenesis"]
];
const mutationUpgradeDescriptions={"Spiked Membrane":["Grow defensive spikes. +8 contact damage.","Spikes lengthen and harden. +8 more contact damage.","Membrane becomes fully barbed. +8 more contact damage."],"Flagella":["Grow a swimming tail. +22% movement speed.","Strengthen the flagella. Another +22% movement speed.","Maximize flagellar thrust. Another +22% movement speed."],"Thick Membrane":["Thicken your outer membrane. +35 max HP and heal 35.","Add another protective membrane layer. +35 max HP and heal 35.","Complete the reinforced membrane. +35 max HP and heal 35."],"Regeneration":["Grow regenerative nodules. Recover 2 HP/sec.","Increase regenerative tissue. +2 additional HP/sec.","Maximize tissue repair. +2 additional HP/sec."],"Dense Cytoplasm":["Densify your cytoplasm. Reduce collision damage by 20%.","Further densify your cytoplasm. Another 20% collision resistance.","Reach maximum density. Another 20% collision resistance."],"Predatory Growth":["Increase body mass and gain +5 contact damage.","Grow larger again and gain another +5 contact damage.","Reach peak predatory size and gain another +5 contact damage."],"Acid Trail":["Secrete a short-lived corrosive slime trail. The trail fades quickly.","Acid becomes stronger and thicker, and the slime remains dangerous noticeably longer.","Create your strongest, thickest acid. The slime persists much longer before fading."],"Pseudopod Lash":["Grow an elastic attacking pseudopod: +5 damage, +10 reach and faster lashes.","Strengthen the lash: another +5 damage, +10 reach and faster recovery.","Perfect the whip: another +5 damage, +10 reach and fastest recovery."],"Clone Carapace":["Clones gain +20 max HP and 20% damage resistance.","Reinforce clone armor: +20 more HP and another 20% resistance.","Complete clone armor: +20 more HP and another 20% resistance."],"Raptor Flagella":["Clones hunt 28% faster.","Further strengthen clone flagella: another +28% speed.","Maximize clone flagella: another +28% speed."],"Clone Fangs":["Clones gain +5 contact damage.","Enlarge clone fangs: another +5 contact damage.","Perfect clone fangs: another +5 contact damage."],"Symbiotic Repair":["Clones regenerate 2 HP/sec.","Improve clone repair: +2 additional HP/sec.","Maximize clone repair: +2 additional HP/sec."],"Brood Expansion":["Increase clone capacity by 1.","Increase clone capacity by 1 again.","Increase clone capacity by 1 again.","Increase clone capacity by 1 again.","Reach maximum clone capacity."],"Spike Launcher":["Grow a hardened automatic spike launcher."]};function mutationChoiceDescription(m){const lv=m[3]?m[3]():0,a=mutationUpgradeDescriptions[m[0]];return a?(a[Math.min(lv,a.length-1)]||a[a.length-1]):m[1]}
const mutationCaps={"Spiked Membrane":3,"Flagella":3,"Thick Membrane":3,"Regeneration":3,"Dense Cytoplasm":3,"Predatory Growth":3,"Acid Trail":3,"Pseudopod Lash":3,"Mitosis":1,"Clone Carapace":3,"Raptor Flagella":3,"Clone Fangs":3,"Symbiotic Repair":3,"Brood Expansion":4,"Accelerated Metabolism":3,"Chemoreception":3,"Reactive Membrane":3,"Cilia":3,"Vacuole Storage":3,"Electrogenesis":4,"Photosynthesis":3,"Toxin Glands":3,"Bioluminescence":3,"Phagocytosis":1,"Dormant Cyst":1,"Adaptive Immunity":3,"Neurotoxin":3,"Osmotic Burst":3,"Spike Launcher":1,"Predatory Engulfment":1,"Genome Duplication":1,"Parasitic Implantation":1,"Cellular Overclock":1,"Amoebic Division":1,"Horizontal Gene Transfer":1};
function mutationLevel(name){if(name==="Spiked Membrane")return p.spikes;if(name==="Flagella")return p.flagella;if(name==="Thick Membrane")return p.membrane;if(name==="Regeneration")return Math.round(p.regen/2);if(name==="Dense Cytoplasm")return Math.round(p.armor/.2);if(name==="Predatory Growth")return p.growth;if(name==="Acid Trail")return p.acidTrail;if(name==="Pseudopod Lash")return p.lashLevel;if(name==="Mitosis")return p.cloneGene?1:0;if(name==="Clone Carapace")return Math.round(p.cloneArmor/.2);if(name==="Raptor Flagella")return Math.max(0,Math.round(Math.log(p.cloneSpeed/118)/Math.log(1.28)));if(name==="Clone Fangs")return Math.max(0,Math.round((p.cloneDamage-11)/5));if(name==="Symbiotic Repair")return Math.round(p.cloneRegen/2);if(name==="Brood Expansion")return broodLevel;if(name==="Electrogenesis")return p.electricLevel;const m=advancedMutations.find(x=>x[0]===name);if(m)return m[3]();if(name==="Spike Launcher")return p.spikeShooter?1:0;return 0}
const mutationSymbols={"Spiked Membrane":"✹","Flagella":"〰","Thick Membrane":"⬡","Regeneration":"✚","Dense Cytoplasm":"◉","Predatory Growth":"▲","Acid Trail":"☣","Pseudopod Lash":"➰","Mitosis":"◌","Clone Carapace":"⬢","Raptor Flagella":"≋","Clone Fangs":"◆","Symbiotic Repair":"✣","Brood Expansion":"◉","Spike Launcher":"➤","Cannibalism":"◒","Emergency Mitosis":"◎","Necrotic Burst":"✺","Hypermetabolism":"⚡","Predatory Membrane":"◈","Electrogenesis":"ϟ","Accelerated Metabolism":"⏱","Chemoreception":"⌁","Reactive Membrane":"◫","Cilia":"≋","Vacuole Storage":"◍","Photosynthesis":"☀","Toxin Glands":"☠","Bioluminescence":"✦","Phagocytosis":"◉","Dormant Cyst":"⬤","Adaptive Immunity":"⛨","Neurotoxin":"☤","Osmotic Burst":"◎","Predatory Engulfment":"◉","Genome Duplication":"⧉","Parasitic Implantation":"♙","Cellular Overclock":"⌁","Amoebic Division":"◐","Horizontal Gene Transfer":"⇄","Stable Genome":"◇"};
const synergySymbols={"Corrosive Membrane":"☢","Caustic Wake":"♨","Living Armor":"✥","Contagious Division":"❉","Rapid Mitosis":"✣","Predatory Colony":"♛","Barbed Tentacle":"〽","Caustic Tendril":"♨","Whiplash":"ϟ","Capacitor Membrane":"⌁","Electropropulsion":"ϟ","Conductive Slime":"⚡","Neural Whip":"ϟ","Shock Spines":"✹","Electric Colony":"⚡","Hyperconductive Metabolism":"ϟ","Rapid Homeostasis":"✚","Hypersecretion":"☣"};
const synergyDescriptions={"Corrosive Membrane":"Enemies that strike your body are burned by corrosive secretions.","Caustic Wake":"Moving quickly spreads a wider, more dangerous acid wake.","Living Armor":"After avoiding damage, your tissue grows a regenerating biological shield.","Contagious Division":"Your clones inherit your acid secretion and leave weaker corrosive trails.","Rapid Mitosis":"Your regenerative tissue accelerates the colony's mitotic recovery.","Predatory Colony":"Clone attacks inherit part of your evolved predatory power.","Barbed Tentacle":"Your pseudopod grows membrane spikes, increasing lash damage.","Caustic Tendril":"Your pseudopod deposits a burst of acid where it strikes.","Whiplash":"Flagella adaptations make the pseudopod snap substantially faster.","Capacitor Membrane":"Your reinforced membrane stores impact charge and releases electrical retaliation.","Electropropulsion":"Fast swimming energizes the electrical field, increasing its reach.","Conductive Slime":"Acid pools conduct your field and shock organisms standing in the trail.","Neural Whip":"Pseudopod strikes carry a stunning electrical impulse.","Shock Spines":"Enemies touching your spikes trigger an extra electrical shock.","Electric Colony":"Clone cells become mobile electrical nodes around the organism.","Hyperconductive Metabolism":"Accelerated metabolism drives Electrogenesis ticks dramatically faster.","Rapid Homeostasis":"Metabolic acceleration improves regenerative recovery.","Hypersecretion":"Metabolic acceleration makes corrosive secretions damage more frequently."};
function mutationInfo(name){for(const m of [...mutations,...cloneMutations,...advancedMutations,...spikeMutations])if(m[0]===name)return m[1];const r=rareMutations.find(x=>x[0]===name);return r?r[1]:"Your genome remains stable."}
function rewardOverlay(title,symbol,name,desc,button="CONTINUE"){active=false;const d=document.createElement("div");d.style.cssText="position:fixed;z-index:35;inset:0;display:flex;align-items:center;justify-content:center;background:rgba(2,8,11,.82);backdrop-filter:blur(6px);padding:22px;text-align:center";d.innerHTML='<div style="width:min(390px,92vw);padding:24px 20px;border:1px solid rgba(160,255,220,.3);border-radius:24px;background:rgba(8,25,27,.94);box-shadow:0 0 45px rgba(91,255,200,.12)"><div style="font-size:11px;letter-spacing:3px;opacity:.65">'+title+'</div><div style="font-size:58px;margin:12px 0 4px">'+symbol+'</div><div style="font-size:27px;font-weight:900">'+name+'</div><div style="font-size:14px;line-height:1.5;opacity:.82;margin-top:10px">'+desc+'</div><button style="margin-top:22px;padding:13px 28px;border:0;border-radius:14px;font-weight:900;font-size:14px">'+button+'</button></div>';document.body.appendChild(d);return new Promise(resolve=>d.querySelector("button").onclick=()=>{d.remove();resolve()})}
function showSynergy(name,req){return rewardOverlay("SYNERGY FORMED",synergySymbols[name]||"✦",name,(req.map(x=>(mutationSymbols[x]||"◇")+" "+x).join(" + "))+"<br><br>"+(synergyDescriptions[name]||"Two completed adaptations have fused into a new biological effect."))}
let pauseLocks=0;
function blockingMenuOpen(){return[...document.querySelectorAll(".overlay")].some(el=>!el.classList.contains("hidden"))||!!document.querySelector(".gene-info-popup")}
function lockGame(){pauseLocks++;active=false}
function unlockGame(){pauseLocks=Math.max(0,pauseLocks-1);active=!pauseLocks&&!blockingMenuOpen()}
function syncMenuFreeze(){if(blockingMenuOpen())active=false}
function resumeCountdown(){lockGame();return new Promise(resolve=>{const d=document.createElement("div");d.style.cssText="position:fixed;z-index:40;inset:0;display:flex;align-items:center;justify-content:center;background:rgba(2,9,11,.32);pointer-events:none";const n=document.createElement("div");n.style.cssText="width:96px;height:96px;border-radius:50%;display:flex;align-items:center;justify-content:center;font:900 46px system-ui;color:white;background:radial-gradient(circle at 32% 26%,rgba(255,255,255,.45),rgba(45,180,150,.82) 35%,rgba(7,47,44,.96));border:2px solid rgba(220,255,245,.75);box-shadow:0 0 28px rgba(91,255,210,.28)";d.appendChild(n);document.body.appendChild(d);let c=3;n.textContent=c;const t=setInterval(()=>{c--;if(c>0)n.textContent=c;else{clearInterval(t);n.textContent="GO";setTimeout(()=>{d.remove();unlockGame();resolve()},420)}},1000)})}
const upgradeColors={"Spiked Membrane":"#d8fff1","Flagella":"#61d9e7","Thick Membrane":"#9fc9ff","Regeneration":"#9dffbd","Dense Cytoplasm":"#607f91","Predatory Growth":"#ff9b6b","Acid Trail":"#83e34f","Pseudopod Lash":"#63e6cf","Mitosis":"#c58cff","Clone Carapace":"#8ea6bb","Raptor Flagella":"#62d6ee","Clone Fangs":"#ff7c91","Symbiotic Repair":"#a8ffd1","Brood Expansion":"#d39cff","Spike Launcher":"#e5f4ff","Cannibalism":"#c87373","Emergency Mitosis":"#d8a5ff","Necrotic Burst":"#a96aff","Hypermetabolism":"#ffe36a","Predatory Membrane":"#ff766d"};
function buildItems(){const out=[];for(const m of [...mutations,...cloneMutations,...spikeMutations]){const lv=mutationLevel(m[0]);if(lv>0)out.push({name:m[0],lv,symbol:mutationSymbols[m[0]]||"◇",color:upgradeColors[m[0]]||"#72cfc1"})}for(const r of rareMutations)if(rareOwned.has(r[2]))out.push({name:r[0],lv:1,symbol:mutationSymbols[r[0]]||"◇",color:upgradeColors[r[0]]||"#d7b5ff"});for(const [name,req] of synergyDefs)if(synergies.has(name))out.push({name,lv:0,symbol:synergySymbols[name]||"✦",color:"#ffd96a",synergy:true,req});return out}
function upgradeColor(name){return upgradeColors[name]||"#72cfc1"}
function glossyIcon(symbol,color,size=29){const c=document.createElement("div");c.style.cssText="width:"+size+"px;height:"+size+"px;border-radius:50%;display:flex;align-items:center;justify-content:center;font:900 "+Math.round(size*.52)+"px system-ui;color:#f8ffff;background:radial-gradient(circle at 31% 25%,rgba(255,255,255,.78),"+color+" 34%,rgba(5,24,27,.96) 100%);border:1px solid rgba(255,255,255,.65);box-shadow:inset -3px -4px 7px rgba(0,0,0,.28),0 1px 6px rgba(0,0,0,.3);text-shadow:0 1px 2px #000";c.textContent=symbol;return c}
function updateBuildRow(){if(!ui.buildRow)return;const items=buildItems(),sig=items.map(x=>x.name+":"+x.lv).join("|");if(ui.buildRow.dataset.sig===sig)return;ui.buildRow.dataset.sig=sig;ui.buildRow.innerHTML="";for(const it of items){const wrap=document.createElement("div");wrap.title=it.name;if(it.synergy){wrap.style.cssText="position:relative;flex:0 0 43px;width:43px;height:34px;margin-left:-3px";const a=it.req&&it.req[0],b=it.req&&it.req[1],ia=glossyIcon(mutationSymbols[a]||"◇",upgradeColor(a),28),ib=glossyIcon(mutationSymbols[b]||"◇",upgradeColor(b),28);ia.style.position="absolute";ia.style.left="1px";ia.style.top="0px";ia.style.zIndex="1";ib.style.position="absolute";ib.style.left="14px";ib.style.top="5px";ib.style.zIndex="2";wrap.appendChild(ia);wrap.appendChild(ib);const badge=document.createElement("div");badge.textContent=it.symbol;badge.style.cssText="position:absolute;right:-1px;bottom:-1px;z-index:3;width:14px;height:14px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:#f5d96b;color:#17201d;border:1px solid rgba(255,255,255,.8);font:900 8px system-ui;box-shadow:0 1px 4px rgba(0,0,0,.4)";wrap.appendChild(badge)}else{wrap.style.cssText="position:relative;flex:0 0 31px;width:31px;height:31px";wrap.appendChild(glossyIcon(it.symbol,it.color,29));if(it.lv){const l=document.createElement("b");l.textContent=it.lv;l.style.cssText="position:absolute;right:-1px;bottom:-2px;min-width:12px;height:12px;padding:0 2px;border-radius:7px;background:#071416;color:#fff;border:1px solid rgba(255,255,255,.6);font:800 8px/12px system-ui;text-align:center";wrap.appendChild(l)}}ui.buildRow.appendChild(wrap)}}
const synergyDefs=[
["Corrosive Membrane",["Acid Trail","Thick Membrane"]],
["Caustic Wake",["Acid Trail","Flagella"]],
["Living Armor",["Thick Membrane","Regeneration"]],
["Contagious Division",["Acid Trail","Brood Expansion"]],
["Rapid Mitosis",["Regeneration","Brood Expansion"]],
["Predatory Colony",["Spiked Membrane","Clone Fangs"]],
["Barbed Tentacle",["Pseudopod Lash","Spiked Membrane"]],
["Caustic Tendril",["Pseudopod Lash","Acid Trail"]],
["Whiplash",["Pseudopod Lash","Flagella"]],["Capacitor Membrane",["Electrogenesis","Thick Membrane"]],["Electropropulsion",["Electrogenesis","Flagella"]],["Conductive Slime",["Electrogenesis","Acid Trail"]],["Neural Whip",["Electrogenesis","Pseudopod Lash"]],["Shock Spines",["Electrogenesis","Spiked Membrane"]],["Electric Colony",["Electrogenesis","Brood Expansion"]],["Hyperconductive Metabolism",["Accelerated Metabolism","Electrogenesis"]],["Rapid Homeostasis",["Accelerated Metabolism","Regeneration"]],["Hypersecretion",["Accelerated Metabolism","Acid Trail"]]
];
function announce(title,sub=""){toast={title,sub,t:2.7};sfx("evolve")}
async function checkSynergies(){const gained=[];for(const [name,req] of synergyDefs){if(synergies.has(name)||req.some(x=>synergyConsumed.has(x)))continue;if(req.every(x=>mutationLevel(x)>=(mutationCaps[x]||99))){synergies.add(name);req.forEach(x=>synergyConsumed.add(x));gained.push([name,req]);break}}if(gained.length){lockGame();updateBuildRow();for(const [name,req] of gained)await showSynergy(name,req);unlockGame();await resumeCountdown()}return gained.length}
function dominantCounter(){const scores={acid:p.acidTrail*3+(synergies.has("Caustic Wake")||synergies.has("Corrosive Membrane")?2:0),colony:(p.cloneGene?2:0)+broodLevel*2+p.cloneDamage/8,armor:p.damage/7+p.spikes*2+p.membrane,interceptor:p.flagella*2+Math.max(0,p.speed/150-1)*5+p.lashLevel};return Object.keys(scores).sort((a,b)=>scores[b]-scores[a])[0]}
function counterName(k){return {acid:"BUFFERED AMOEBA",colony:"BROOD HUNTER",armor:"SHELLBACK",interceptor:"INTERCEPTOR"}[k]||"ADAPTED PREDATOR"}
function addInstability(n=1){instability+=n;const nt=Math.min(4,Math.floor(instability/6));if(nt>adaptationTier){adaptationTier=nt;const k=dominantCounter();announce("ECOSYSTEM ADAPTING",counterName(k)+" organisms are emerging in response to your build.")}}
function grantRandomMutation(){const pool=[...mutations,...(p.cloneGene?cloneMutations:[])].filter(m=>!m[4]||m[3]()<m[4]);if(pool.length&&Math.random()<.82){const m=pool[Math.floor(Math.random()*pool.length)];m[2]();if(p.cloneGene&&cloneMutations.includes(m)&&clones.length<p.cloneCount)spawnClone();addInstability(1);return m[0]}const avail=rareMutations.filter(r=>r[2]==="electrogenesis"?p.electricLevel<4:!rareOwned.has(r[2]));if(avail.length){const r=avail[Math.floor(Math.random()*avail.length)];if(r[2]==="electrogenesis"){p.electricLevel=Math.min(4,p.electricLevel+1);rareOwned.add(r[2]);announce("RARE MUTATION — ELECTROGENESIS "+["","I","II","III","IV"][p.electricLevel],(p.electricLevel*3)+" damage per field tick.")}else{rareOwned.add(r[2]);announce("RARE MUTATION — "+r[0],r[1])}return r[0]}return "Stable Genome"}
